M115.03,77.25c0,8.62-4.64,16.16-11.57,20.25.33-.43,3.13-4.06,1.97-8.52-1.03-3.94-4.69-6.89-9.13-7.24-5.83,2.47-16.32,6.02-29.78,5.72-11.82-.25-21.08-3.35-26.67-5.72-4.44.35-8.1,3.3-9.13,7.24-1.16,4.46,1.64,8.09,1.97,8.52-6.93-4.09-11.57-11.63-11.57-20.25,0-3.91.94-7.59,2.64-10.84l.02-.02c.35-.66.73-1.31,1.14-1.94,1.16-2.14,2.97-5.68,4.06-9.86,5.19-16.66,20.72-28.82,39.09-28.82s33.91,12.16,39.09,28.82c1.09,4.18,2.9,7.72,4.06,9.86.41.63.8,1.28,1.14,1.94l.02.02c1.69,3.25,2.64,6.93,2.64,10.84Z" style="fill:#535282;"/><path d="M68.08,100.73s-6.06.35-10.57-2.2c4.21,3.21,10.57,3.58,10.57,3.58,0,0,6.36-.37,10.57-3.58-4.51,2.55-10.57,2.2-10.57,2.2Z" style="opacity:.2;"/><polygon points="49.05 88.98 54.17 94.52 57.52 91.75 49.05 88.98" style="fill:#b5b9c3;"/><polygon points="87.12 88.98 82 94.52 78.65 91.75 87.12 88.98" style="fill:#b5b9c3;"/><path d="M90.92,100.72c.18-.4,5.09-4.03,5.42-16.52s-6.9-16.84-6.9-16.84c0,0,9.75,3.08,9.75,17.72,0,14.64-1.99,14.93-2.45,15.09-1.17.26-2.72.6-5.81.55Z" style="opacity:.2;"/><path d="M45.2,100.72c-.18-.4-5.09-4.03-5.42-16.52-.33-12.5,6.9-16.84,6.9-16.84,0,0-9.75,3.08-9.75,17.72s1.99,14.93,2.45,15.09c1.17.26,2.72.6,5.81.55Z" style="opacity:.2;"/><polygon points="46.69 72.89 48.16 72.4 51.41 75.06 46.69 72.89" style="opacity:.2;"/><polygon points="87.12 72.89 85.64 72.4 82.4 75.06 87.12 72.89" style="opacity:.2;"/><path d="M25.76,53.9s1.04-2.47,3.4-4.32c-1.62,5.62,4.35,8.36,4.35,8.36,0,0,.82-4.58,2.6-9.61,1.3,4.44,10.63,5.57,10.63,5.57,0,0-1.03-3.94,1.66-8.66,11.7,1.48,22.33,7.08,22.33,7.08,0,0-.66-2.66-2.64-6.94,4.6,5.5,23.54,9.85,23.54,9.85,0,0-2.22-.98-4.5-5.08,10.62,4.96,30.64,7.49,35.81,3.65-4.87-2.36-11.37-8.12-19.05-13.44,2.22-.3,10.93,2.22,15.51,4.29-4.28-9.89-13.59-23.78-25.08-24.51,3.13-2.07,6.62-1.18,12.26-2.22-11.48-9.16-44.78-14.47-52.66-6.18,1.14-4.02,4.18-6.51,4.93-8.88-7.23,0-12.11,6.35-12.11,6.35,0,0,0-3.69,0-7.24-3.54,1.33-6.2,9.93-6.2,9.93-8.27.93-16.88,4.54-18.76,9.41,3.98-1.67,7.14-2.57,7.14-2.57,0,0-8.7,8.77-8.88,17.04,1.74-1.48,3.71-2.54,3.71-2.54,0,0-3.75,4.08,2.01,20.66Z" style="fill:#100f33;"/></svg>', 'Zeke is a retired harbor security officer and longtime resident of SouthPort, best known for his imposing frame, sharp tongue, and unshakable confidence.', '<strong>Zeke</strong> is a retired harbor security officer and longtime resident of [SouthPort](/wiki/southport), best known for his imposing frame, sharp tongue, and unshakable confidence. Once tasked with keeping order along the port-side, he now lives a slower-paced life with his husband, [Azrian](/wiki/azrian-harborne). Whether it''s by choice or by consequence depends on who you ask. Beneath his smug exterior is a surprisingly thoughtful (if somewhat lazy) shark with a taste for the finer things in life, including food, attention, and the occasional teasing remark. Despite stepping away from the job, Zeke remains a familiar face in SouthPort and an enigma to those trying to figure out just how seriously to take him.', 'Character', '["zeke-harborne","shark","redrift"]', 'both', 3, '2026-04-20T06:48:01.550Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-AH', 'azrian-harborne', 'Azrian Harborne', NULL, 'Azrian is a quiet, steady presence in SouthPort, best known for his work maintaining the harbor and his tendency to appear where no one expects him.', '<strong>Azrian</strong> is a quiet, steady presence in [SouthPort](/wiki/southport), best known for his work maintaining the harbor and his tendency to appear where no one expects him. Tall and unassuming with the faint glow of an angler-fish''s lure, he carries an air of mystery that makes it hard to tell whether he''s simply private or keeping something unspoken. Married to [Zeke](/wiki/zeke-harborne), Azzy balances his husband''s larger-than-life energy with patience and quiet indulgence, often letting Zeke take center stage while he lingers just out of focus. Most people see him as the maintenance man who keeps the harbor running, but there are whispers that Azzy has a way of knowing and/or being more than he ever admits out loud.', 'Character', '["azrian-harborne","anglerfish","redrift"]', 'both', 4, '2026-04-20T08:10:13.671Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-TYP-XW', 'xor-wulff', 'Xor Wulff', NULL, 'Xor is a calico cat with a sharp mind, a sharper tongue, and a strong preference for solitude.', '<strong>Xor</strong> is a calico cat with a sharp mind, a sharper tongue, and a strong preference for solitude. Known mostly for his past involvement in a now-defunct band, Xor has since distanced himself from group projects and large crowds alike. A quiet weaponry nerd and longtime bassist, he channels most of his focus into personal study and creative work. While his sarcasm can come off as cold, he''s more thoughtful than most people realize; he''s just not the type to advertise it.', 'Character', '["cat","xor-wulff","redrift"]', 'both', 5, '2026-04-20T08:11:28.985Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-WE', 'wyvern-embers', 'Wyvern Embers', NULL, 'Wyvern is the guy who pokes ghosts with a stick to see what happens. He''s the type of guy to walk into an abandoned factory at 2 in the morning with a camcorder in one hand and a half-eaten shrimp taco in the other.', '<strong>Wyvern</strong> *(pronounced "whiv-urn")* is the guy who pokes ghosts with a stick to see what happens. He''s the type of guy to walk into an abandoned factory at 2 in the morning with a camcorder in one hand and a half-eaten shrimp taco in the other. A proud member of the [Ashford Paranormal Society (APS)](/wiki/aps), Wyvern somehow manages to be both the instigator and the guy holding the flashlight. He leans into chaos without really thinking twice, and while he might not take everything seriously, he never backs down when things get weird.', 'Character', '["dragon","cat","wyvern-embers","redrift"]', 'both', 6, '2026-04-20T08:12:13.499Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-JU', 'judas-umbra', 'Judas Umbra', NULL, 'Judas is... complicated. They show up when you least expect them to, disappear without a trace, and know more about yourself than you do, probably.', '<strong>Judas</strong> is... complicated. They show up when you least expect them to, disappear without a trace, and know more about yourself than you do, probably. Despite this ominous aura, they''re not evil, or at least they don''t intend to be. They''re just... weirdly condescending and cryptic. They play the long game, often keeping secrets "for your own good," which is both irritating and endearing depending on who you ask.', 'Character', '["judas-umbra","redrift","dragon"]', 'both', 7, '2026-04-20T08:13:17.982Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-L', 'leo', 'Leo', NULL, 'hi my name is leo', 'hi my name is <strong style="color: var(--wiki-accent-color);">leo</strong> logan told me to tell you im not cannon to [redrift](/wiki/redrift) or whatever idk what that means but here''s my wiki page :D', 'Character', '["leo","wickerbest"]', 'sfw', 8, '2026-04-20T10:04:59.087Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-G', 'gizmanta', 'Gizmanta', NULL, 'There''s honestly not a lot to say about Gizmanta, but I wanted to give him a wiki page anyways.', '<strong>Gizmanta</strong> is not canon to the [REDRIFT](/wiki/redrift) universe, I just wanted to make a protogen character. There''s honestly not a lot to say about him. However, I''ll still humor you, reader. Here''s a bunch of bullshit about this clanker.', 'Character', '["gizmanta","protogen"]', 'both', 9, '2026-04-20T10:36:40.226Z', CURRENT_TIMESTAMP);
INSERT INTO wiki_entries (id, slug, label, relation_icon_svg, summary, intro, entry_type, tags_json, visibility, sort_order, published_at, updated_at) VALUES ('WIKI-CHR-KF', 'kevin-foster', 'Kevin Foster', NULL, 'Kevin was the father of both Logan and Jesper, remembered as a tired but well-meaning man who spent much of his life behind a camera.', '<strong>Kevin</strong> was the father of both [Logan](/wiki/logan-foster) and [Jesper](/wiki/jesper-foster), remembered as a tired but well-meaning man who spent much of his life behind a camera. Though he carried the title of "Media Director," his reality was long hours, low pay, and the grind of camerawork and editing. Kevin had a habit of documenting everyday life on VHS, a practice that made him seem invasive to some but was, in truth, his way of holding onto fleeting moments. Misunderstood and often stretched thin, he balanced ambition with exhaustion, leaving behind fragments of who he was and what he enjoyed on tape.', 'Character', '["kevin-foster","raccoon","redrift"]', 'both', 10, '2026-04-20T10:57:31.279Z', CURRENT_TIMESTAMP);
