INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-LF', 'I''m making a comeback!', 'https://media.raccstarlogan.com/wiki/assets/char/lf/q.mp3', 'Logan', 'voiced by me!', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-LF-APRC', 'WIKI-CHR-LF', 'appearance', 'Appearance', replace('Logan is a raccoon with fluffy, medium blue-gray fur, a puffed out tail, and sharp blue eyes. His hair is always swooped to his left, and he has a slit in his left eyebrow, of which the origin is unknown. He has a red heart-shaped marking on his chest, which is also of unknown origin.\n\nHe usually wears a navy-blue t-shirt and blue jeans under a fairly thin red flannel hoodie with black sleeves, paired with red, black and blue Converse sneakers that are worn from running around and getting into trouble. In colder weather, he swaps the flannel jacket for a thick, dark gray winter coat with a light gray lining, and an off-white cream t-shirt underneath.\n\n[[NSFW]]He has a humanoid penis with foreskin which is pretty small when soft, but around average sized if not slightly big when hardened.\n\nDuring his later years, he is on the extremely severe end of obesity, with a saggy belly hanging down over his knees, huge moobs protruding from his chest, thick thighs that could save lives, and an ass that could end them. His arms are notably flabby, and his pudgy hands make it hard to hold onto small objects. His face is noticeably a lot fluffier and unkempt than in his younger years.[[/NSFW]]','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-LF-PRSN', 'WIKI-CHR-LF', 'personality', 'Personality', replace('Logan tends to be quite impulsive and reckless. Most people will call him stupid because of this, but he''s actually pretty clever and resourceful when he wants to be. He just has a really bad habit of not thinking things through, which gets him into a lot of trouble. When first meeting him, he can be a bit shy and awkward, but given some time, he''ll act somewhat derpy if he takes a liking towards you; otherwise, he doesn''t talk much and can come off as standoffish. He''s got quite a niche but dry sense of humor; a lot of his jokes don''t land unless you specifically know what he''s referencing.\n\n[[NSFW]]In bed, Logan is very submissive, to the point that he won''t make any advances himself unless you push him hard enough. He likes to act dominant, but as soon as the action starts, he''ll chicken out. That''s probably why he''s still a virgin.\n\nDuring his later years, he''s a lot more careless than before, not wanting to get up to do most things (not that he could anyways). He spends more time eating and lazing around than he does thinking, but when he does actually have a thought, you can tell he''s in a depressive state. Sure, his dick is hard, but that doesn''t fix everything.[[/NSFW]]','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-LF-HSTR', 'WIKI-CHR-LF', 'history', 'History', replace('Logan spent most of his childhood in [EastUnder Valley](/wiki/eastunder-valley), a quiet suburb of [San Bandera](/wiki/san-bandera), living with his single mother, [Emily](/wiki/emily-foster). Life there was constantly shifting; Emily had a rough time finding a stable partner, and Logan ended up with a revolving door of "new dads," each one sticking around for a few years/months before vanishing. One in particular seemed like he''d last, but a sudden midlife crisis tore things apart. The fallout left Logan and his mom without a home midway through his sophomore year of high school.\n\nThey relocated to [Ashford](/wiki/ashford), a rural town just up north that Logan wasn''t used to, but it''s where he first started digging into his interest in abandoned places. There, he met a friend named [Wyvern](/wiki/wyvern-embers), who introduced him to paranormal investigation, weird theories, and a general fascination with the unknown. The two spent a lot of time exploring the outskirts of town, which were rumored to be more than a little... off.\n\nEventually, financial strain forced another move, this time back to San Bandera. Logan and his mom ended up in [SouthPort](/wiki/southport), a neglected port-side district where Logan would eventually graduate high school. He hated that school; the staff were strict, the atmosphere was suffocating, but he made it through. After graduation, he found an old, abandoned mobile home and just... claimed it. Nobody stopped him, so he stayed.\n\nIn 2023, Logan met his long-lost brother [Jesper](/wiki/jesper-foster) by chance at a bus stop. It didn''t take long to piece together that they were related on his father [Kevin](/wiki/kevin-foster)''s side. Without hesitation, Logan offered him a place to stay. Jesper reluctantly accepted.\n\nNot long after, Logan stumbled across a strange book hidden deep within an abandoned forest library. It was old, written in some strange, bizarre and foreign language, and it hummed with an eerie energy. He brought it home. He shouldn''t have. But he did.\n\n[And that''s where things really start.](/portfolio/projects/redrift)\n\n[[NSFW]]In his later years, Logan began exploring long-standing "adult" interests he had previously kept to himself... mostly. What started as a quiet fascination with weight gain gradually turned into active experimentation, with him intentionally pushing his limits further and further as time progressed. At first, he treated it as something temporary, something he could stop or reverse whenever he felt like it, but that assumption slowly slipped out of his control.\n\nAs time went on, his habits became routine, and the line between curiosity and dependency blurred. By his mid-to-late 30s, his condition had escalated significantly, leaving him severely obese and largely confined to his home. The situation placed increasing strain on his relationship with Jesper, who eventually moved out, unable to handle both the responsibility and the emotional weight of watching Logan continue down that path. Left on his own, Logan was forced to face the weight of his actions he had long dismissed as manageable.[[/NSFW]]','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-LF-ABLT', 'WIKI-CHR-LF', 'abilities', 'Abilities', 'TODO: Rewrite this section from the old ToyHouse description.', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-DRNK', 'WIKI-CHR-LF', 'He will drink anything as long as it''s not bodily fluids.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-POP', 'WIKI-CHR-LF', 'He doesn''t give a rat''s ass about current events or celebrity gossip, leaving him mostly uncultured.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-GOOF', 'WIKI-CHR-LF', 'He will often just goof off for the hell of it up until you tell him to stop. (May take multiple attempts.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-CHUB', 'WIKI-CHR-LF', 'He uses eating as a coping mechanism whenever he''s upset, causing him to be decently chubby. He doesn''t mind this.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-HLTH', 'WIKI-CHR-LF', 'He has a severe weight gain fetish, to the point he gets off to health issues caused by excessive fat.', 1, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-ATSM', 'WIKI-CHR-LF', 'He''s been diagnosed with Asperger''s Syndrome, leaving him on the Autism spectrum. One of his schools scrubbed his diagnosis from his record because he "didn''t seem autistic enough."', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-LAMA', 'WIKI-CHR-LF', 'He''s *extremely* afraid of llama plushies... for some reason.', 0, 6);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-FART', 'WIKI-CHR-LF', 'He''s a known fat fetish artist on a niche artwork sharing website, going under a different alias.', 1, 7);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-BLUR', 'WIKI-CHR-LF', 'He tends to blur the line between comfort and indulgence, often not noticing when one becomes the other.', 1, 8);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-SELF', 'WIKI-CHR-LF', 'He can be weirdly self-aware about his own issues, but that awareness doesn''t always translate into actually changing anything.', 1, 9);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-DCLN', 'WIKI-CHR-LF', 'He has a tendency to romanticize or normalize his own decline when he''s in a bad mental state.', 1, 10);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-DBLE', 'WIKI-CHR-LF', 'He''s more likely to double down on a bad habit than stop it once it''s become routine.', 1, 11);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-LF-CARE', 'WIKI-CHR-LF', 'Despite acting carefree most of the time, he gets frustrated with himself easily when he realizes he''s messed something up.', 0, 12);
