INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-JF', 'If I wanted you dead, we wouldn''t be talking.', NULL, 'Jesper', NULL, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JF-APRC', 'WIKI-CHR-JF', 'appearance', 'Appearance', replace('Jesper is a tall, undead raccoon-lynx hybrid with a lean, muscular build. His fur is deep charcoal black with reddish undertones, complimented by an unusually large and fluffy raccoon tail and tufted lynx ears. His hair is long, thick, and unkempt, reaching down past his shoulders. He has heterochromia with one red eye and one yellow eye. His body shows signs of wear: a large X-shaped scar over his chest, claw marks across his back, and a noticeable scar around his lower side, all from past encounters.\n\nJesper''s usual attire consists of a beat-up black leather jacket (usually unzipped and shirtless underneath, but if he has to wear a shirt he''ll wear a deep burgundy tank top), black jeans, and steel-toed tactical combat boots. He wears a mask made from his father’s skull, which has been modified to fit his face. The mask is often cracked and chipped, showing signs of wear and tear from his various missions and encounters. He also wields a chain wallet and a knife holster, with the knife also chained.\n\n[[NSFW]]He has a hybrid humanoid/barbed penis which can be hidden pretty well, except for the rare off chance he gets hard, in which it sticks out like an exposed wire. I don''t know how to expand this because I''m afraid of keylogging.[[/NSFW]]','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JF-PRSN', 'WIKI-CHR-JF', 'personality', 'Personality', replace('Jesper puts on a blunt, assertive attitude, but behind closed doors, he''s surprisingly chill to be around. As an undead mercenary, he''s used to people fearing him, and honestly, he''s okay with that. It comes with the territory.\n\nHe tends to be immediately suspicious of newcomers, especially outside of work or family. If you''re not someone he expects to be around, he straight up doesn''t trust you at ALL.\n\nHowever, if you do manage to earn his trust, he''s a loyal and protective friend who would go to great lengths to keep you safe. His sense of humor leans heavily dark, not out of malice, but it''s just how he processes the world around him, given his past.\n\n[[NSFW]]Jesper has a strongly dominant disposition, though it''s not something he expresses openly. He requires a significant level of trust before allowing that side of himself to surface, and even then, it tends to emerge quickly and decisively rather than gradually. His libido is typically low but can increase sharply under the right conditions of which he actively tries to conceal. He is highly controlled in most aspects of his life, which makes that shift more pronounced when it does occur, though he remains reluctant to discuss it or acknowledge it outright.[[/NSFW]]','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JF-HSTR', 'WIKI-CHR-JF', 'history', 'History', replace('Jesper''s childhood was split between two drastically different worlds. His mother, [Zelda](/wiki/zelda-voss), was strict and no-nonsense, while his father [Kevin](/wiki/kevin-foster) was a chaotic mess of a man clinging to what little control he had. The two shared custody with Zelda in [San Bandera](/wiki/san-bandera) and Kevin in [SouthPort](/wiki/southport), but Kevin was always fighting for full rights. Jesper was stuck in the middle, quietly enduring the emotional strain like it was just part of life.\n\nThe day Kevin finally won custody was the same day everything fell apart. On the drive home, their car hydroplaned and flew off the road into a ditch, bashing into oncoming traffic on the way, triggering an explosion. Kevin didn''t make it out. Technically, Jesper didn''t either, but something pulled him back.\n\nHe woke up undead, confused, alone, and missing huge pieces of who he used to be. The only thing he had from the wreck was a cracked raccoon skull he''d found near the site, Kevin''s skull, but Jesper wouldn''t realize that for a long time. He started wearing it like armor, more instinct than sentiment.\n\nWith no memory, no guidance, and no sense of belonging, Jesper wandered for a while, trying to piece together who and what he even was. Eventually, he was approached by [Alison Cross](/wiki/alison-cross), who offered him rehabilitation as long as he was willing to work as a mercenary for her. Jesper accepted, and over time, he became one of her most reliable and skilled operatives, taking on high-risk missions that others wouldn''t dare touch.\n\n[[NSFW]]Much of Jesper''s personal development was shaped by environments where control and discipline were prioritized above all else, leaving little room for vulnerability or self-exploration. As a result, he developed a tendency to suppress or compartmentalize more personal aspects of himself, relying heavily on control as a means of stability. This has made certain parts of his behavior feel unfamiliar or difficult to process, particularly when they conflict with the image he maintains.\n\nHe has made isolated attempts to understand certain aspects of himself, though most of the time these efforts were short-lived and rarely acknowledged afterward.[[/NSFW]]\n\nYears passed. Then one day, Jesper met his long-lost brother, [Logan](/wiki/logan-foster), at a random bus stop in southern Downtown San Bandera. Something about them felt off, yet familiar. Jesper couldn''t explain it, but deep down, he knew this guy mattered to him. So, when Logan offered to let him move into their place, he reluctantly accepted, not sure what to expect. Life didn''t get any simpler, especially with Logan around, but it started to feel a bit more real again.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JF-ABLT', 'WIKI-CHR-JF', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-BVOR', 'WIKI-CHR-JF', 'Being Logan''s older brother, he tends to act as their voice of reason.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-SCLM', 'WIKI-CHR-JF', 'He doesn''t use social media; it''s too much of a distraction for him. He also fears that most sites request too much personal info.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-WSKY', 'WIKI-CHR-JF', 'He will go to bars on occasion, but usually, it''s just because he''s bored out of his mind with absolutely nothing to do. His drink of choice is usually a whiskey on the rocks, but he''ll also drink beer or whatever''s available.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-CMNL', 'WIKI-CHR-JF', 'Before meeting Alison, he''s been arrested multiple times for various murder-related charges, but they were all dropped due to the help of Alison offering to expunge the charges from his record.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-FEAR', 'WIKI-CHR-JF', 'He has a deep-seated fear of losing control, stemming from his chaotic upbringing and the traumatic events that led to his undead state.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-PHTO', 'WIKI-CHR-JF', 'He doesn''t remember anything of who he was before the accident with Kevin, but when given clues about his past he gets unexpectedly emotional. He has a photo of himself when he was 9 and his dad at a museum somewhere in his wallet.', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-CARS', 'WIKI-CHR-JF', 'He is deathly afraid of cars. He will avoid them by all means necessary.', 0, 6);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-MEOW', 'WIKI-CHR-JF', 'On rare occasions, he''ll have cat-like tendencies. He doesn''t know why, since he''s completely unaware of his lineage.', 0, 7);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-CNBL', 'WIKI-CHR-JF', 'He has a history of cannibalism, but he''s laid off in recent years.', 0, 8);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-GTAR', 'WIKI-CHR-JF', 'If he''s completely alone and there''s a guitar nearby, he''ll play it, usually only during moments of severe distress.', 0, 9);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-LEFT', 'WIKI-CHR-JF', 'He''s left-handed.', 0, 10);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-SHRA', 'WIKI-CHR-JF', 'The lyrics ["I''m still alive, but something died in me ages long ago"](https://genius.com/Ivycomb-sahara-lyrics#:~:text=belowI%27m%20still%20alive%20but%20something%20died%20in%20me%20ages%20long%20ago) from the song ["SAHARA" by Ivycomb](https://www.youtube.com/watch?v=VQywoIhcNC8) heavily influenced his character early on when I was still trying to figure out who he was.', 0, 11);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-VORE', 'WIKI-CHR-JF', 'He has a thing for vore, he often acts as the predator, but he either is too busy or shy to admit that to anyone.', 1, 12);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-HUGS', 'WIKI-CHR-JF', 'He has a complicated relationship with physical closeness, often unsure how to respond to it.', 1, 13);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-KNOW', 'WIKI-CHR-JF', 'He knows about Logan''s secret fat fetish artwork. Logan doesn''t keep it hidden very well.', 1, 14);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-SBND', 'WIKI-CHR-JF', 'He has, on occasion, experimented with Logan''s "SwellBind" spell in private, largely out of curiosity and desire to understand Logan''s attachment to it. He shudders every time.', 1, 15);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-DOMM', 'WIKI-CHR-JF', 'He is scarily dominant, but it takes a lot to get him comfortable enough to actually show you that side of him.', 1, 16);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JF-BDSM', 'WIKI-CHR-JF', 'Some of his scars are from previous sexual encounters. Let''s just put it that way.', 1, 17);
