INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-JS', 'Go back home to your *grave*, you z\*mbie *FREAK!*', 'https://media.raccstarlogan.com/wiki/assets/char/js/q.mp3', 'Jason, to Jesper', 'voiced by Plantastrophe', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JS-APRC', 'WIKI-CHR-JS', 'appearance', 'Appearance', replace('Jason is a lean shark with slate-blue skin and a muscular, slim build. His head features a sharp snout, angry purple eyes, and a dark navy mohawk with blue highlights. Three gill slits are visible on each side of his neck but are often confused for the scars on his chest. A dorsal fin runs down his back into his tail.\n\nJason''s most common outfit consists of a black denim vest with the sleeves ripped off and blue jeans. While on duty, he''s seen carrying a trident slung over his shoulder, with a deep-purple gem at the base of the brass prongs.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JS-PRSN', 'WIKI-CHR-JS', 'personality', 'Personality', replace('Jason is fiercely competitive and always acts like he has something to prove, even if nobody’s watching.\n\nHe''s the type to insert himself into a challenge just to win, whether it''s necessary or not. His opinions are LOUD, often unfiltered, and delivered with full chest regardless of how wrong he might be. He thrives off attention, regardless of what kind, and seems to confuse confidence with correctness. He has a very black-and-white worldview and is quick to judge people based on surface-level impressions. He''s also very easily offended and will hold grudges for a long time if he thinks he''s been disrespected.\n\nOn the surface, Jason comes off as tough, cocky, and ready to fight, but if things don''t go his way, that tough exterior cracks just enough to show how emotionally immature he can be. He doesn''t throw tantrums so much as he gets defensive and combative, especially when called out or proven wrong. He''s not used to being underestimated, and when it happens, he takes it personally.\n\nHe tries to act like the cool, edgy twin, but most people around him see right through it. His idea of subtlety is... very un-subtle. Underneath the bravado, there''s a weird need for validation that he never really addresses.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JS-HSTR', 'WIKI-CHR-JS', 'history', 'History', replace('Jason grew up in SouthPort alongside his twin brother Zeke, though you wouldn''t know they were related by how differently they act. In school, Jason was the loud one, the show-off, the guy who thought every hallway was his stage. He hit his personal peak in high school; star athlete, center of attention, and completely insufferable about it.\n\nDespite all the noise he made, he was constantly overshadowed by Zeke, whose quiet capability made more impact than Jason''s constant bragging. That contrast stuck with Jason, and whether he admits it or not, it''s one of the reasons he pushes himself so hard now, trying to outshine a shadow he pretends not to notice.\n\nAfter graduation, Jason was enlisted by his father [Vincent](/wiki/vincent-skank) to work as a mercenary, and he''s been doing that ever since. He talks like he''s top-class, but in reality, he''s barely scraping by on sheer bravado and lucky breaks. Most of his "successes" come from charging in without a plan and somehow surviving. He''s gotten into serious trouble numerous times, and there''s a rumor that the only reason he''s still enlisted is because someone higher up (probably his dad) keeps tugging strings to keep him involved.\n\nHe still insists he''s better than his twin, even as Zeke quietly builds a real life with his husband [Azrian](/wiki/azrian-harborne) and leaves Jason behind in nearly every metric that matters.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JS-ABLT', 'WIKI-CHR-JS', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JS-ATTN', 'WIKI-CHR-JS', 'He can and will spread misinformation if it means it will give him attention.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JS-CMPS', 'WIKI-CHR-JS', 'His moral compass seems to be either stuck or nonexistent.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JS-FANS', 'WIKI-CHR-JS', 'He has a fan account dedicated to him on social media. He''s the one who runs it.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JS-GRND', 'WIKI-CHR-JS', 'Zeke once grounded him as an adult, and it actually worked, unsurprisingly.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JS-OPHN', 'WIKI-CHR-JS', 'Both him and Zeke grew up as orphans for reasons still unknown. It''s probably because their dad has dangerous ties. It''s definitely because their dad has dangerous ties.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JS-ASHL', 'WIKI-CHR-JS', 'Yes, he''s an asshole. You don''t have to tell me.', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-JS-RACT', 'WIKI-CHR-JS', 'He thrives on reactions, positive or negative, as long as he''s getting attention.', 0, 6);
