INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-ZH', 'You''d be surprised what kind of damage I can do just by leaning forward.', 'https://media.raccstarlogan.com/wiki/assets/char/zh/q.mp3', 'Zeke', 'voiced by [RoyalFoil](https://www.castingcall.club/royal_foil01)', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-ZH-APRC', 'WIKI-CHR-ZH', 'appearance', 'Appearance', replace('Zeke is a very heavyset shark with a stocky build that reflects years of indulgence more than his former profession. His body is broad and imposing, with thick limbs, a wide belly, and distinct stretch marks around his midsection and sides. He has short, jagged stripes across his arms and tail.\n\nHis body is a cool gray with hints of blue, especially in the shadows. His stripes are darker gray with a slight indigo tint. His hair is black with a faint blue shine. His belly and inner arms are lighter, but the contrast is subtle and keeps the whole palette feeling soft.\n\nHe typically wears a severely ill-fitting tank top that struggles to contain his size, often riding up due to his size, and a pair of brown cargo shorts that sit snugly around his hips. A golden key pendant always hangs from his neck, a sentimental keepsake he rarely speaks about. Despite his size, he carries himself with ease, unbothered and confident in how he looks.\n\nHis weight sits mostly around his middle, giving him a soft, rounded belly that leads the way wherever he goes. His chest follows suit, full and broad, while his arms and legs, though thick, carry less of the bulk. His backside is notably wide and heavy as well, rounding out his silhouette with an almost exaggerated balance. It''s clear his body has adapted over time, settling into comfort rather than combat.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-ZH-PRSN', 'WIKI-CHR-ZH', 'personality', 'Personality', 'Zeke is basically the opposite of his brother, Jason. He''s a LOT more laid back, but still relatively cocky...just in a slower, more smug manner. He tends to speak in a calm, confident drawl, often teasing others with a smirk that says he knows exactly what he''s doing. While he doesn''t seek attention the same way Jason does, he has a habit of making his presence known with quiet swagger and sharp wit. He''s not easily rattled, rarely raises his voice, and has an annoying talent for getting under people’s skin without lifting a finger. Despite this, he''s approachable, easy to talk to, and surprisingly patient, especially with people he cares about. He enjoys pushing buttons but usually knows where the line is. *Usually.*', 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-ZH-HSTR', 'WIKI-CHR-ZH', 'history', 'History', replace('Zeke grew up in Southport with his twin brother Jason, though you wouldn''t guess they were related at first glance. Where Jason was loud and desperate to be seen, Zeke was quiet, grounded, and effortlessly competent. He didn''t care much for popularity, but that didn''t stop people from noticing him anyway, especially teachers, coaches, and the occasional crush Jason couldn''t quite win over.\n\nHe never chased the spotlight, but he didn''t avoid it either. Zeke made his way into harbor security not long after graduation, quickly earning a reputation for readability and strength. He rarely talked about his job, but those close to him knew he took it seriously. When he began developing health issues that made the job unsustainable, it hit him harder than he''d ever admit. For a while, he felt lost, like he had nothing left to prove, but also nothing left to do.\n\nThat changed when he met Azrian. The two first crossed paths during a routine harbor patrol. Azrian had been sketching the old dockyards for an art project and wasn''t exactly supposed to be there. Zeke nearly wrote him up, but Azrian''s flustered charm and quick wit made an impression. What started as an awkward warning turned into a casual conversation, then a coffee date, then something neither of them expected.\n\nIt was the first time Zeke felt truly seen, not for what he could do or how he measured up to others, but for who he already was. With Azrian, he didn''t have to perform, prove, or pretend. The connection gave Zeke a reason to slow down, to start prioritizing comfort, intimacy, and long ignored desires he''d kept tucked away for years.\n\nNow retired and living with his husband, Zeke found comfort in simplicity. He doesn''t chase attention, doesn''t seek validation, and (unlike Jason) no longer needs to prove anything to anyone...except for how much fried shrimp he can stuff into his mouth at once.','\n',char(10)), 'markdown', 0, 2);
