INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-AH', 'He *says* he doesn''t need seconds, but somehow there''s always room when I''m around.~', NULL, 'Azrian', NULL, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-APRC', 'WIKI-CHR-AH', 'appearance', 'Appearance', replace('Azrian''s wardrobe is minimal: he almost exclusively wears a pair of durable blue overalls, usually with the top half rolled down or clipped loose when off duty. They''re practical, water-resistant, and patched in places from years of use. He rarely bothers with shirts underneath unless the weather demands it. The overalls are simply easier for him to work in, and he''s long since stopped pretending otherwise.\n\nHis skin tone is a dark aquamarine, fading to a gray underbelly that runs from his chin down his chest and abdomen. His body is mostly smooth and unmarked, though faint gradients deepen around his arms, tail, and back. The lack of strong patterning gives him a clean, uniform appearance that contrasts sharply with his glowing features.\n\nHis husband''s mannerisms have rubbed off on him more than he''d like to admit, and Azzy has a habit of snacking throughout the day, whether that be taste testing his own cooking or just keeping some homemade snack mix nearby. This means he''s not skinny either, in fact he''s pushing obesity, but he''s not nearly as obese as Zeke. But I mean, you can''t trust a skinny cook, am I right?\n\nHis eyes, lure, and fin edges emit a bright cyan-teal light, which stands out vividly in low light. Subtle veins of the same glow trace through parts of his fins and tail, giving them a bioluminescent shimmer without overpowering his main coloration.\n\nTwo small, curved fins sit on the sides of his head. Not really horns, just simple shapes that frame his face and keep him from looking too bare. They match his skin tone and blend naturally into his design without drawing too much attention.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-PRSN', 'WIKI-CHR-AH', 'personality', 'Personality', replace('Azzy keeps a quiet, steady presence that makes him easy to underestimate at first glance. He isn''t loud or flashy, and most people know him as reserved, thoughtful, and sometimes a little difficult to read. He doesn''t open up quickly, preferring to let silence carry conversations until he has something worth saying.\n\nThat said, there''s a warmer side to him once he relaxes. Azzy has a teasing streak that slips out in subtle ways, never sharp enough to sting but just enough to catch someone off guard. He enjoys small, everyday comforts (cooking, evening walks, collecting odd little maritime trinkets) and tends to show care through actions rather than words.\n\nHe avoids unnecessary conflict and rarely raises his voice, though that doesn''t mean he''s passive. When something matters to him, he holds firm. His patience makes him good at handling long hours, tedious tasks, or stubborn people. While not the most expressive on the surface, Azzy''s presence has a grounding effect, giving the sense of someone who sees more than he lets on.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-BHCD', 'WIKI-CHR-AH', 'behind-closed-doors', 'Behind Closed Doors', replace('Azzy''s affection shows itself in ways that are impossible to mistake once you see them. He doesn''t just enjoy Zeke''s size; he actively embraces and feeds into it. Cooking meals WAY bigger than necessary, always making sure food is close by, slipping in extra portions without comment... These aren''t accidents. He actively encourages Zeke to indulge, sometimes teasingly, sometimes with a quiet push, but always with the intent of seeing him satisfied and heavier than before.\n\nWhat might look like simple spoiling from the outside is deliberate on Azzy''s part. He takes pride in being the one who keeps Zeke full and then some, and in knowing his efforts show over time. It''s not framed as a joke or a passing quirk, it''s just how he loves.\n\nFor Azzy, there''s a quiet satisfaction in this ritual. Watching Zeke soften, noticing shirts fit tighter, or seeing the way he sinks a little deeper into a chair, these are things Azzy quietly treasures. They''re signs that his care is working, that his presence leaves a mark. It''s a slow, ongoing process that he takes pride in, and it''s a core part of how he expresses love. Each added pound feels like proof of his devotion: something visible, tangible, and deeply personal. Zeke himself doesn''t always acknowledge the changes, but when he does, it''s usually just a smirk. However, sometimes, it''s a tug at his shirt to emphasize the stretch, a deliberate lean into Azzy that leaves no room to ignore it. Those moments always fluster him, though he hides it poorly, and Zeke, of course, knows *exactly* what he''s doing.','\n',char(10)), 'markdown', 1, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-HSTR', 'WIKI-CHR-AH', 'history', 'History', replace('Azzy grew up in SouthPort, spending most of his life near the harbor where work was steady but rarely glamorous. He developed a quiet reputation as someone who could fix what others left broken, from machinery to minor infrastructure, and found comfort in the solitude of late-night shifts. While others might have seen harbor maintenance as thankless work, Azrian valued its rhythm and the small freedoms it gave him.\n\nFor years, he kept to himself, more comfortable with tools and tide charts than with conversation. He wasn''t unfriendly, but his tendency to deflect personal questions with humor or silence kept most people at arm''s length. That changed when he crossed paths with Zeke during a routine harbor patrol. Azrian hadn''t exactly been where he was supposed to be, sketching at the old dockyards under poor lighting, and nearly earned himself a write-up. Instead, the awkward warning turned into an unexpected conversation. Zeke''s grounded presence and straightforward nature drew Azrian out of his shell in a way nobody else had.\n\nWhat began as small talk stretched into shared coffee, then regular meetups, and eventually something deeper. With Zeke, Azrian discovered a kind of companionship that didn''t demand he hide his quirks or his quiet habits. Their bond grew steadily, and over time, marriage followed.\n\nNow settled with his husband, Aziran still works in and around the harbor, though his focus has shifted. He finds joy in the mundane: cooking meals, maintaining their home, and providing the sort of stability that allows Zeke to slow down. For Azzy, fulfillment lies not in recognition, but in the quiet life they''ve built together.','\n',char(10)), 'markdown', 0, 3);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-AH-ABLT', 'WIKI-CHR-AH', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-WRTN', 'WIKI-CHR-AH', 'His handwriting is surprisingly neat, almost calligraphic, despite his otherwise rough, practical nature.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-RDIO', 'WIKI-CHR-AH', 'He has a quiet fondness for late-night radio shows and sometimes leaves them playing softly while he works.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-LTRN', 'WIKI-CHR-AH', 'Though he dislikes bright artificial lighting, he owns several lanterns and candles, claiming they "make the dark feel friendlier."', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-SKCH', 'WIKI-CHR-AH', 'He rarely finishes a sketchbook, often abandoning it halfway once he feels it''s "served its purpose."', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-MURL', 'WIKI-CHR-AH', 'Azzy painted a mural of Zeke near his old station around the time of his retirement, leaving a quiet tribute to his work, despite being short-lived.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-COOK', 'WIKI-CHR-AH', 'He claims he "cooks too much by accident," though anyone close to him knows it isn''t really an accident.', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-MTWG', 'WIKI-CHR-AH', 'At one point he had a phase where he tried gaining weight himself, alongside Zeke, but he stopped after realizing how hard things would become in the long run.', 1, 6);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-AZOF', 'WIKI-CHR-AH', 'He and Zeke ran a paid subscription documenting Zeke''s weight gain, which helps fund most of the food Azrian cooks for him.', 1, 7);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-AH-GFTI', 'WIKI-CHR-AH', 'There are sometimes hidden graffiti doodles at the harbor Azzy works at that hint at him and Zeke''s future. They are promptly removed or covered up the next day.', 1, 8);
