INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-TYP-XW', replace('I uh, don''t do bands anymore. Last one just kinda, well... We didn''t quite get along as much as I''d hoped we would.\n\nGosh, that [Judas](/wiki/judas-umbra) chick was a handful.','\n',char(10)), 'https://media.raccstarlogan.com/wiki/assets/char/xw/q.mp3', 'Xor', 'voiced by [HueShiftVA](https://www.castingcall.club/hueshiftva)', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MO6YTJTS-8NA85', 'WIKI-TYP-XW', 'appearance', 'Appearance', replace('Xor is tall and lean with a naturally serious expression and sharp, angular features that make him perpetually unimpressed even when he''s not. His fur is mostly a pale tan with jagged, asymmetrical markings in gold and dark brown, especially along his tail and face. His hair follows a similar pattern, with blonde at the top but cutting into brown towards the lower half, naturally matching his fur coloration. It''s swept to the side, layered with jagged sunburns, and extends into a short mullet that he clearly doesn''t maintain for fashion purposes, but it works for him anyway.\n\nA defining feature is his thick, sharply split eyebrow, giving his resting glare a bit more weight than he probably intends. Combined with his posture (usually slouched and half done with the room) it adds to the aura of someone who''d rather be anywhere else.\n\nXor typically wears a natural-tone shirt, usually tan, with dark navy jeans, and a dark gray pullover hoodie. Around his neck is a turquoise pendant, a gift from his grandmother and one of the few sentimental items he keeps close.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MO6YTJXX-5NKJ6', 'WIKI-TYP-XW', 'personality', 'Personality', replace('Xor is self-reserved and quietly observant, often choosing silence over small talk. He doesn''t go out of his way to connect with others, but he''s not hostile either, just guarded. Most people read him as indifferent or distant, but those who actually earn his trust quickly learn he''s got a sharp sense of humor and a mean streak of sarcasm he uses like a scalpel. If he''s teasing you, it probably means he likes you.\n\nHe''s not one for crowds, noise, or surface-level conversation. He prefers solitude, especially when it means he can focus on studying weapons, design theory, or music on his own terms. While not particularly spiritual, he occasionally attends contemporary church services; though, it''s more about reflection than belief, and even then, only if he''s awake in time.\n\nXor rarely talks about his past, particularly his time in a now-defunct band, and avoids group projects where possible. He works best alone or in quiet company, and values sincerity over social norms. He''s thoughtful in ways people don''t always expect, and while he won''t say it outright, he pays attention to everything and everyone.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MO6YTK21-W4JXZ', 'WIKI-TYP-XW', 'history', 'History', replace('Not much is publicly known about Xor''s past, and that''s exactly how he prefers it. During his college years, he was part of a band, though he doesn''t speak fondly of the experience. The way he phrases it, things didn''t exactly end on the best of terms, especially with one particular band member. He hasn''t joined another group since.\n\nOutside of that chapter, the only visible connection to his past is the turquoise pendant he wears daily, a gift from his grandmother. Whether it''s sentiment, guilt, or comfort, he''s never said. What''s clear is that whatever pieces of history he keeps, he guards them tightly.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-MO6YTK60-0MYL7', 'WIKI-TYP-XW', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-XW-LASR', 'WIKI-TYP-XW', 'Laser pointers are his worst enemy.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-XW-ZLDA', 'WIKI-TYP-XW', 'While he doesn''t usually collect weapons, he does have a sword that looks suspiciously like one that belongs to a certain green-clad hero.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-XW-FLIP', 'WIKI-TYP-XW', 'He uses the same flip phone he''s had since childhood; he hasn''t found a need to upgrade it.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-XW-BCFE', 'WIKI-TYP-XW', 'He almost always drinks his coffee black.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-XW-TIME', 'WIKI-TYP-XW', 'If he hears a song with a weird time signature, he''ll stop whatever he''s doing to try and parse it out.', 0, 4);
