INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-WE', 'I''m ''verning it', NULL, 'Wyvern', NULL, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-WE-APRC', 'WIKI-CHR-WE', 'appearance', 'Appearance', replace('Wyvern is a cat-dragon hybrid with a digitigrade build, mixing feline proportions with more noticeable dragon traits. His overall shape leans more dragon-like, mainly due to his large bat-like wings and long, thick tail, while his face and general structure stay closer to a cat. He also has short horns that curve slightly back behind his ears.\n\nHe has sharp blood-red eyes with slit pupils and yellow sclera, usually giving him a tired or unimpressed look. His hair is bright red and slightly messy, falling forward enough to partially cover one eye. His colors are mostly warm browns with darker limbs, broken up by strong red accents in his hair, claws, and the inner parts of his wings.\n\nWyvern usually wears a purple jacket with a darker torso over a black shirt, along with dark shorts. His clothing gives him a more casual, modern look that contrasts with his more “fantastical” features, keeping the design grounded overall.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-WE-PRSN', 'WIKI-CHR-WE', 'personality', 'Personality', replace('Wyvern comes off loud, but he rarely says much about himself. He''s quick with a joke, rarely serious, and usually has a sarcastic take ready for whatever''s going on. If something awkward happens, odds are he''s the one that caused it; either it be on purpose or because he wasn''t paying attention.\n\nHe''s the type to fill the silence with noise: commentary, side-eye, or a dry one-liner. But underneath it, he pays closer attention than people give him credit for. He avoids vulnerability like the plague but cares more than he lets on. If you need someone to laugh with at 3 in the morning or walk into a haunted building just because, he''s probably already outside waiting for you to catch up.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-WE-HSTR', 'WIKI-CHR-WE', 'history', 'History', replace('Wyvern was born in (note to self come up with an in universe equivalent of Brooklyn, NY) before moving down to Ashford, Texaria halfway through elementary school.\n\nBack in school, he had a brief stint as an internet troll. Not the malicious kind, just the "spends too much time on forums pissing people off" kind. He doesn''t bring it up often, but every now and then someone recognizes his username, and he has to deny everything with a straight face, at least as straight as he can keep it.\n\nHis history is unremarkable for the most part, other than the fact that he''s always been drawn to the weird and spooky. He was the kid who would dare his friends to go into the woods at night, and as he got older, that curiosity only grew stronger. Joining the APS was a natural fit for him, and he''s been an active member ever since, always on the lookout for the next big paranormal adventure.','\n',char(10)), 'markdown', 0, 2);
