INSERT INTO wiki_quotes (entry_id, quote_text, audio_url, attribution, voice_credit, nsfw_only) VALUES ('WIKI-CHR-JU', replace('I don''t owe you an explanation.\nYou wouldn''t believe me anyway.','\n',char(10)), 'https://media.racctarlogan.com/wiki/assets/char/ju/q.mp3', 'Judas', 'voiced by [Constellist](https://vgen.co/constellist)', 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-APRC', 'WIKI-CHR-JU', 'appearance', 'Appearance', replace('Judas has dark gray scales marked with black striping. Their eyes glow a vivid violet, contrasting against their swept black hair streaked with a pastel purple. Curved horns, clawed hands, and three distinct tails make their silhouette immediately recognizable. Their bat-like wings are black with sharp purple striping along the edge, matching the lavender tones of their claws and hair streaks.\n\nThey''re most often seen wearing a spiked black choker and bracelets that reinforce their punk aesthetic. They also sometimes wear a dark purple vest with the sleeves ripped off. It''s absolutely a stylistic choice, no denying that.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-PRSN', 'WIKI-CHR-JU', 'personality', 'Personality', replace('Judas is calm and deliberate, rarely raising their voice or losing composure. They prefer to keep people guessing, speaking in clipped truths or half-answers that often feel more like riddles. While they aren''t intentionally cruel, their dry delivery and habit of withholding details can come across as condescending to those who don''t know them well.\n\nDespite the connections to the libraries they''re often seen near and their weird knowledge of magic and the occult, they refuse to act like a holier-than-thou oracle. They carry the weight of their role with resignation more than pride, treating it more like a side hobby than a responsibility. Away from that, they''re unexpectedly approachable (sarcastic at times, even a little playful) and let their guard down enough to enjoy late-night outings or impromptu stage performances.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-HSTR', 'WIKI-CHR-JU', 'history', 'History', replace('Judas was never truly "born" in the traditional sense, they simply began to exist. From their first moment of awareness, the only home they have known was the strange library they now reside in, of which the location remains a complete mystery. Much of their early life was spent exploring the library''s endless shelves, absorbing whatever knowledge they could reach. Books on arcane theory and magical practice quickly became their favorites, shaping Judas into a fluent, if unorthodox, practitioner of magic.\n\nAmong these countless texts, one volume stood out: a manuscript that seemed to outline a prophecy. Some of its passages were inconsistent, as though it had been altered or rewritten at some point, but Judas never confirmed if this was intentional or accidental. They''ve kept its meaning close ever since, rarely sharing more than a vague mention of "what''s coming." For Judas, the prophecy feels less like destiny and more like an obligation they were saddled with.\n\nOutside the library, Judas once tried living a more ordinary life. During college, they fronted a band alongside Xor Wulff, taking the role of the lead vocalist. Their performances were intense and charismatic, but behind the scenes the group was volatile. Judas'' stubborn streak and habit of shutting down arguments with cryptic remarks clashed with other members, often leaving tensions unresolved. Their brief relationship with Xor only added to the strain, what began as creative chemistry quickly soured under the weight of the band''s internal conflicts. The group eventually fell apart, with Judas often blamed as one of the sparks that set the breakup in motion.\n\nThough they rarely talk about this period, echoes of it remain. On rare nights out, Judas will step on stage at a local bar, singing with the same haunting energy that once defined them. It''s one of the few glimpses into the life that they might''ve chosen, had the library not claimed them first.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-JU-ABLT', 'WIKI-CHR-JU', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70T8HS-CLEXJ', 'WIKI-CHR-JU', 'They refuse to eat chicken if it''s not *specifically* from Larrie''s™.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70TOXM-FRKPI', 'WIKI-CHR-JU', 'Their magic aura glows a deep violet and leaves faint afterimages. Some say you can read things in the trails if you know what to look for', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70U9D6-LC7BQ', 'WIKI-CHR-JU', 'Occasionally they''ll show up in people''s dreams. They say it''s accidental; it''s not.', 0, 2);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70UNHE-8KXRY', 'WIKI-CHR-JU', 'They''re technically a "prophet" but insist that it''s more of a side thing.', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70V3WN-QSS6Y', 'WIKI-CHR-JU', 'They somehow always have exact change.', 0, 4);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70VB8M-U76ET', 'WIKI-CHR-JU', 'They have a surprisingly high alcohol tolerance and impeccable karaoke skills.', 0, 5);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70VN14-WDJED', 'WIKI-CHR-JU', 'They have a habit of humming or singing under their breath when they think nobody''s listening.', 0, 6);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70W19S-G9DM6', 'WIKI-CHR-JU', 'They treat bar trivia nights like a serious competition. They usually win.', 0, 7);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70WGRZ-Z1X07', 'WIKI-CHR-JU', 'On rare nights, they''ll volunteer to run lights or effects at small shows, using magic for "visual flair" without anyone realizing it isn''t stage tech.', 0, 8);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70X2ZV-I9V8H', 'WIKI-CHR-JU', 'Despite being careful with magic in serious situations, they''ve been known to use small spells purely for mischief, like flickering streetlamps or setting off automatic doors nearby.', 0, 9);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO70XQN5-UX9H2', 'WIKI-CHR-JU', 'Across [Avalona](/wiki/upa), bus drivers trade stories about Judas appearing on their routes. They''ll ride quietly for a few stops with no clear destination, then vanish without anyone noticing when they get on or off. Some swear the seat is empty the moment they glance back.', 0, 10);
