INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-G-APRC', 'WIKI-CHR-G', 'appearance', 'Appearance', replace('Gizmanta is a sleek, raccoon-like common protogen with cool gray fur and darker gray markings on his paws and tail. His displays show two colors, those being blue and red. His accents (inner ears, paw pads and claws) are asymmetrical, mirroring his screen colors opposite of each side.\n\nHe typically only wears a brown blazer alongside his usual protogen armor, which is a pearl white color. On his chest plate, you can see a very subtle power indicator light which flashes white when turned on, red when low on battery, and blue when charging.','\n',char(10)), 'markdown', 0, 0);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-G-PRSN', 'WIKI-CHR-G', 'personality', 'Personality', replace('Gizmanta is commonly described as a nerd, but that''s no insult! He''s very knowledgeable and surprisingly fast with math. Which isn''t surprising considering he''s literally a computer and has the knowledge of the entire internet at his disposal.\n\nHe doesn''t exactly get most jokes; he tends to take things too literally. His own jokes are about as cheesy as any "personal assistant" on your phone or computer or LLM would make.','\n',char(10)), 'markdown', 0, 1);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-G-HSTR', 'WIKI-CHR-G', 'history', 'History', replace('Gizmanta was created in a lab from a sample of [Logan](/wiki/logan-foster)''s DNA. The reasoning behind this has since been forgotten, but hey, he exists, and that''s all that really matters.\n\nNowadays, he exists as a quiet presence in the background; helpful, nerdy, and slightly out of sync with social cues.','\n',char(10)), 'markdown', 0, 2);
INSERT INTO wiki_sections (id, entry_id, section_key, section_title, section_body, section_format, nsfw_only, sort_order) VALUES ('WIKI-SEC-G-ABLT', 'WIKI-CHR-G', 'abilities', 'Abilities', 'TODO', 'markdown', 0, 3);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO72QT39-57R9X', 'WIKI-CHR-G', 'Because he was made from Logan''s DNA, the two are basically cousins.', 0, 0);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO72R3FD-3F3NV', 'WIKI-CHR-G', 'Hi name is a combination of "gizmo" and "antonio", the latter being the name of the scientist behind his creation.', 0, 1);
INSERT INTO wiki_trivia (id, entry_id, item_text, nsfw_only, sort_order) VALUES ('WIKI-TRIVIA-MO72RKLA-LTTT9', 'WIKI-CHR-G', 'His voice is basically just the default voice that comes with desktop assistants like Bonzi Buddy from the early 2000''s.', 0, 2);
